# ######## CELL 17: language-recognition benchmark (character trigrams), full pipeline ########
# Estimated run time: ~4-5 h on an 8-core High-RAM CPU runtime (no GPU needed), ~3-4 h on 12 cores:
#   crossbar simulation ~2.5 h, sigma estimates ~0.5 h, closed form v1 ~0.5 h, v2 ~0.5 h.
# The classic HDC benchmark that Karunaratne et al. (2020, PCM chip) and Huang et al. (2026,
# ReRAM chip) ran in hardware: 22 European languages, 21,000 test sentences, trigram encoding
# h = sign(sum rho^2(L) * rho(L) * L). The text corpus is cloned once from GitHub
# (abbas-rahimi/HDC-Language-Recognition, fixed commit) into data/langid.
# D = 512 / 1024 / 2048, seeds 0-2, all six training rules, FP32 / 4-bit / binary, three
# devices, eight chips; then the calibration-chip estimates and the closed forms v1 and v2.
# Outputs: results/v2_langid.jsonl, v2_langid_pred.jsonl, v2_langid_analytic.jsonl,
# v2_langid_analytic2.jsonl. Every step is resumable: if the session drops, run the cell again.

DRIVE_DIR = "/content/drive/MyDrive/hdc_memristive"

import os, subprocess, sys, pathlib
from google.colab import drive
drive.mount("/content/drive")
work = pathlib.Path(DRIVE_DIR); (work / "code_langid").mkdir(parents=True, exist_ok=True)

FILES = {'hdc.py': '"""Hyperdimensional computing (HDC) with class prototypes stored in a memristive crossbar.\n\nPipeline\n  1. Encode each sample with a random projection: h = sign(x P), P ~ N(0, 1)^(F x D),\n     giving bipolar query hypervectors that drive the crossbar rows as +/-V pulses.\n  2. Train class prototypes in software: one bundling pass (sum of class hypervectors),\n     then optional perceptron-style retraining epochs (standard in HDC literature).\n  3. L2-normalise each prototype (dot product -> cosine similarity) and quantise it to\n     the chosen precision (fp / k-bit / binary).\n  4. Program the prototypes into an AIHWKit inference tile with a device noise model\n     calibrated on real hardware (PCM, NeuRRAM ReRAM, CMO/HfOx ReRAM), let them drift\n     for time t, and classify by argmax over the analog dot products.\nEvery (device, D, precision, t) point is evaluated over several independently\nprogrammed "chips" (Monte Carlo) so device-to-device spread shows up as variance.\n"""\nfrom __future__ import annotations\n\nimport warnings\nfrom dataclasses import dataclass\n\nimport numpy as np\nimport torch\n\nwarnings.filterwarnings("ignore")\n\n# ----------------------------------------------------------------------------- data\nOPENML = {  # name -> (openml name, version, standard split)\n    "isolet": ("isolet", 1, None),\n    "ucihar": ("har", 1, None),\n    "mnist": ("mnist_784", 1, 60000),\n    "fmnist": ("Fashion-MNIST", 1, 60000),\n    "letter": ("letter", 1, None),\n    "pendigits": ("pendigits", 1, None),\n    "satimage": ("satimage", 1, None),\n}\nALL_DATASETS = list(OPENML)\n\n# European language recognition (Joshi, Halseth, Kanerva 2016; Rahimi et al. ISLPED 2016):\n# 22 training languages, 21,000 test sentences (21 languages; Afrikaans has no test set).\nLANGID_REPO = "https://github.com/abbas-rahimi/HDC-Language-Recognition"\nLANGID_COMMIT = "b3be34dd7caa2dc0c13be60447e74956e64cfd33"\nLANGID_LABELS = ["afr", "bul", "ces", "dan", "nld", "deu", "eng", "est", "fin", "fra", "ell",\n                 "hun", "ita", "lav", "lit", "pol", "por", "ron", "slk", "slv", "spa", "swe"]\nLANGID_TEST = {"af": "afr", "bg": "bul", "cs": "ces", "da": "dan", "nl": "nld", "de": "deu",\n               "en": "eng", "et": "est", "fi": "fin", "fr": "fra", "el": "ell", "hu": "hun",\n               "it": "ita", "lv": "lav", "lt": "lit", "pl": "pol", "pt": "por", "ro": "ron",\n               "sk": "slk", "sl": "slv", "es": "spa", "sv": "swe"}\nLANGID_CHUNK = 150      # training sample length (characters), close to the mean test sentence\nLANGID_PER_LANG = 2000  # training chunks drawn per language\nLANGID_MAXLEN = 1200    # longest test sentence is 1,138 characters\nN_SYMBOLS = 27          # a-z and space; any other character is read as a space\n\n\ndef _trigram_ids(text: str, maxlen: int) -> np.ndarray:\n    """Trigram index sequence (c[t-2]*729 + c[t-1]*27 + c[t]), padded with -1."""\n    c = np.frombuffer(text.lower().encode("latin-1", "replace"), dtype=np.uint8).astype(np.int32) - 97\n    c = np.where((c >= 0) & (c < 26), c, 26)[:maxlen]\n    g = c[:-2] * 729 + c[1:-1] * 27 + c[2:] if len(c) >= 3 else np.zeros(0, np.int32)\n    out = np.full(maxlen, -1, np.int16)\n    out[:len(g)] = g\n    return out\n\n\ndef _load_langid(data_home: str):\n    import os\n    import subprocess\n    from pathlib import Path\n    root = Path(data_home) / "langid"\n    cache = root / "langid_trigrams_v1.npz"\n    if cache.exists():\n        z = np.load(cache)\n        return z["Xtr"], z["ytr"], z["Xte"], z["yte"], len(LANGID_LABELS)\n    repo = root / "repo"\n    if not (repo / "training_texts").exists():\n        root.mkdir(parents=True, exist_ok=True)\n        subprocess.run(["git", "clone", "-q", LANGID_REPO, str(repo)], check=True)\n        subprocess.run(["git", "-C", str(repo), "checkout", "-q", LANGID_COMMIT], check=True)\n    rng = np.random.default_rng(0)\n    Xtr, ytr = [], []\n    for k, lab in enumerate(LANGID_LABELS):\n        txt = (repo / "training_texts" / f"{lab}.txt").read_text(encoding="latin-1")\n        starts = np.arange(0, len(txt) - LANGID_CHUNK, LANGID_CHUNK)\n        for s0 in np.sort(rng.choice(starts, size=min(LANGID_PER_LANG, len(starts)), replace=False)):\n            Xtr.append(_trigram_ids(txt[s0:s0 + LANGID_CHUNK], LANGID_CHUNK))\n            ytr.append(k)\n    Xte, yte = [], []\n    for f in sorted(os.listdir(repo / "testing_texts")):\n        if f.split("_")[0] in LANGID_TEST and f.endswith("_p.txt"):\n            Xte.append(_trigram_ids((repo / "testing_texts" / f).read_text(encoding="latin-1"),\n                                    LANGID_MAXLEN))\n            yte.append(LANGID_LABELS.index(LANGID_TEST[f.split("_")[0]]))\n    pad = np.full((len(Xtr), LANGID_MAXLEN - LANGID_CHUNK), -1, np.int16)\n    Xtr = np.concatenate([np.stack(Xtr), pad], 1)\n    out = (Xtr, np.array(ytr, np.int64), np.stack(Xte), np.array(yte, np.int64))\n    np.savez_compressed(cache, Xtr=out[0], ytr=out[1], Xte=out[2], yte=out[3])\n    return (*out, len(LANGID_LABELS))\n\n\ndef load_dataset(name: str, data_home: str = "./data", seed: int = 0):\n    """Returns min-max normalised float32 (Xtr, ytr, Xte, yte) and the class count.\n    MNIST / Fashion-MNIST keep their official 60k/10k split; the other OpenML sets are\n    split 80/20, stratified, with a fixed seed."""\n    if name == "langid":  # trigram index sequences, no feature normalisation\n        return _load_langid(data_home)\n    if name == "digits":  # offline smoke-test set\n        from sklearn.datasets import load_digits\n        d = load_digits()\n        X, y, n_train = d.data.astype(np.float32), d.target, None\n    elif name == "synth":  # offline, harder: 20 overlapping classes (method prototyping only)\n        from sklearn.datasets import make_classification\n        X, y = make_classification(n_samples=12000, n_features=64, n_informative=32,\n                                   n_redundant=16, n_classes=20, n_clusters_per_class=1,\n                                   class_sep=2.0, random_state=0)\n        X, n_train = X.astype(np.float32), None\n    else:\n        from sklearn.datasets import fetch_openml\n        oname, ver, n_train = OPENML[name]\n        X, y = fetch_openml(oname, version=ver, return_X_y=True, as_frame=False,\n                            data_home=data_home, parser="auto")\n        X = X.astype(np.float32)\n    y = np.unique(y, return_inverse=True)[1].astype(np.int64)\n    if n_train:\n        Xtr, ytr, Xte, yte = X[:n_train], y[:n_train], X[n_train:], y[n_train:]\n    else:\n        from sklearn.model_selection import train_test_split\n        Xtr, Xte, ytr, yte = train_test_split(X, y, test_size=0.2, stratify=y, random_state=seed)\n    lo, hi = Xtr.min(0), Xtr.max(0)\n    scale = np.where(hi > lo, hi - lo, 1.0)\n    Xtr, Xte = (Xtr - lo) / scale, np.clip((Xte - lo) / scale, 0, 1)\n    return Xtr.astype(np.float32), ytr, Xte.astype(np.float32), yte, int(y.max() + 1)\n\n\n# ----------------------------------------------------------------------------- HDC\ndef _bipolar(z: torch.Tensor) -> torch.Tensor:\n    return torch.where(z >= 0, 1, -1).to(torch.int8)\n\n\nclass Encoder:\n    """Random-projection encoder h = sign((x - mean) P). With a mean the training-set feature\n    mean is removed first, which strips the common-mode component that non-negative\n    features otherwise put into every hypervector (it wastes ADC range on the crossbar)."""\n\n    kind = "rp"\n\n    def __init__(self, n_features: int, dim: int, seed: int = 0, mean: np.ndarray | None = None):\n        g = torch.Generator().manual_seed(seed)\n        self.P = torch.randn(n_features, dim, generator=g)\n        self.mean = None if mean is None else torch.as_tensor(mean, dtype=torch.float32)\n\n    def centre(self, X) -> torch.Tensor:\n        X = torch.as_tensor(X)\n        return X - self.mean if self.mean is not None else X\n\n    def pre(self, X) -> torch.Tensor:\n        """Input vector that multiplies P (drives the encoder crossbar rows)."""\n        return self.centre(X).float()\n\n    def post(self, z: torch.Tensor) -> torch.Tensor:\n        """Projection output z = pre(x) P -> bipolar hypervector."""\n        return _bipolar(z)\n\n    @torch.no_grad()\n    def __call__(self, X: np.ndarray, bs: int = 4096) -> torch.Tensor:\n        X = self.pre(X)\n        out = torch.empty(len(X), self.P.shape[1], dtype=torch.int8)  # +/-1, 1 byte each\n        for i in range(0, len(X), bs):\n            out[i:i + bs] = self.post(X[i:i + bs] @ self.P)\n        return out\n\n\nclass NonlinearEncoder(Encoder):\n    """OnlineHD-style nonlinear encoder, binarised for the crossbar:\n    h = sign(cos(x P + b) * sin(x P)), b ~ U(0, 2 pi), with each (centred) sample scaled to\n    unit L2 norm first, as in OnlineHD / MM-HDC, so x P has unit variance."""\n\n    kind = "nonlinear"\n\n    def __init__(self, n_features: int, dim: int, seed: int = 0, mean=None):\n        super().__init__(n_features, dim, seed, mean)\n        g = torch.Generator().manual_seed(seed + 7)\n        self.b = torch.rand(dim, generator=g) * 2 * np.pi\n\n    def pre(self, X) -> torch.Tensor:\n        X = self.centre(X).float()\n        return X / X.norm(dim=1, keepdim=True).clamp_min(1e-12)\n\n    def post(self, z: torch.Tensor) -> torch.Tensor:\n        return _bipolar(torch.cos(z + self.b) * torch.sin(z))\n\n\nclass IDLevelEncoder:\n    """Record-based ID-level encoder: h = sign(sum_f ID_f * L_{q(x_f)}), with random bipolar\n    ID vectors per feature and L correlated level vectors (L_0 random; each next level flips\n    a fresh block of D / (2 (L-1)) components, so L_0 and L_{L-1} are ~orthogonal).\n    Features are expected in [0, 1] (min-max normalised); ties go to +1."""\n\n    kind = "idlevel"\n\n    def __init__(self, n_features: int, dim: int, seed: int = 0, levels: int = 16, mean=None):\n        g = torch.Generator().manual_seed(seed)\n        self.ids = torch.where(torch.rand(n_features, dim, generator=g) < 0.5, -1.0, 1.0)\n        lv = torch.empty(levels, dim)\n        lv[0] = torch.where(torch.rand(dim, generator=g) < 0.5, -1.0, 1.0)\n        order = torch.randperm(dim, generator=g)\n        step = dim // (2 * (levels - 1))\n        for k in range(1, levels):\n            lv[k] = lv[k - 1]\n            lv[k, order[(k - 1) * step:k * step]] *= -1\n        self.lv, self.levels = lv, levels\n\n    @torch.no_grad()\n    def __call__(self, X, bs: int = 2048):\n        X = torch.as_tensor(X)\n        q = torch.clamp((X * (self.levels - 1)).round().long(), 0, self.levels - 1)\n        out = torch.empty(len(X), self.ids.shape[1], dtype=torch.int8)\n        for i in range(0, len(X), bs):\n            qb = q[i:i + bs]\n            acc = torch.zeros(len(qb), self.ids.shape[1])\n            for f in range(self.ids.shape[0]):\n                acc += self.ids[f] * self.lv[qb[:, f]]\n            out[i:i + bs] = _bipolar(acc)\n        return out\n\n\nclass NGramEncoder:\n    """Character trigram encoder of the language-recognition benchmark (Rahimi et al. 2016):\n    h = sign(sum_t rho^2(L[c_{t-2}]) * rho(L[c_{t-1}]) * L[c_t]), with random bipolar letter\n    vectors L and rho a cyclic shift by one position. Implemented as h = sign(n T), where n\n    holds the trigram counts and T the 27^3 trigram hypervectors. Input: padded trigram index\n    sequences from load_dataset("langid"); ties go to +1."""\n\n    kind = "ngram"\n\n    def __init__(self, dim: int, seed: int = 0):\n        g = torch.Generator().manual_seed(seed)\n        L = torch.where(torch.rand(N_SYMBOLS, dim, generator=g) < 0.5, -1.0, 1.0)\n        R1, R2 = torch.roll(L, 1, 1), torch.roll(L, 2, 1)\n        self.T = (R2[:, None, None] * R1[None, :, None] * L[None, None, :]).reshape(-1, dim)\n\n    @torch.no_grad()\n    def __call__(self, X, bs: int = 1024):\n        X = torch.as_tensor(np.asarray(X)).long()\n        out = torch.empty(len(X), self.T.shape[1], dtype=torch.int8)\n        for i in range(0, len(X), bs):\n            xb = X[i:i + bs]\n            r, c = torch.nonzero(xb >= 0, as_tuple=True)\n            n = torch.sparse_coo_tensor(torch.stack([r, xb[r, c]]), torch.ones(len(r)),\n                                        (len(xb), self.T.shape[0])).coalesce()\n            out[i:i + bs] = _bipolar(torch.sparse.mm(n, self.T))\n        return out\n\n\ndef make_encoder(kind: str, n_features: int, dim: int, seed: int, Xtr: np.ndarray,\n                 center: bool = True):\n    if kind == "ngram":\n        return NGramEncoder(dim, seed)\n    mean = Xtr.mean(0) if center else None\n    if kind == "rp":\n        return Encoder(n_features, dim, seed, mean)\n    if kind == "rp_bipolar":  # same random projection, entries replaced by their signs (+/-1)\n        e = Encoder(n_features, dim, seed, mean)\n        e.P = torch.where(e.P >= 0, 1.0, -1.0)\n        e.kind = "rp"\n        return e\n    if kind == "nonlinear":\n        return NonlinearEncoder(n_features, dim, seed, mean)\n    if kind == "idlevel":\n        return IDLevelEncoder(n_features, dim, seed)\n    raise ValueError(kind)\n\n\n@torch.no_grad()\ndef train_prototypes(H: torch.Tensor, y: np.ndarray, n_classes: int,\n                     retrain_epochs: int = 0, lr: float = 0.05, seed: int = 0,\n                     margin: float = 0.0, adaptive: bool = False,\n                     flip_p: float = 0.0) -> torch.Tensor:\n    """Single-pass bundling, then perceptron-style retraining.\n\n    margin = 0  : classic HDC retraining (update only misclassified samples).\n    flip_p > 0 : query hypervector bits are flipped at random during retraining (noise\n                 injection as in DependableHD); combined with a fixed margin it is that baseline.\n    margin = g>0: margin-aware retraining (proposed). A sample also triggers an update when\n                  its cosine margin s_true - max_{c != true} s_c is below g, pushing it away\n                  from the strongest competitor. With g = kappa * sigma_hat (sigma_hat = std of\n                  the analog similarity error, estimated on training data), retraining trades\n                  a little digital fitting for margins that survive device noise.\n    Cosines use L2-normalised prototypes and hypervectors scaled by 1/sqrt(D)."""\n    y = torch.as_tensor(y)\n    M = torch.zeros(n_classes, H.shape[1])\n    for i in range(0, len(y), 8192):  # single-pass bundling\n        M.index_add_(0, y[i:i + 8192], H[i:i + 8192].float())\n    # class-mean initialisation: makes `lr` a relative step independent of class size\n    # (with a plain sum, one update moves a 6000-sample MNIST prototype by ~1/6000)\n    M /= torch.bincount(y, minlength=n_classes).clamp_min(1)[:, None].float()\n    g = torch.Generator().manual_seed(seed)\n    inv_sqrt_d = 1.0 / np.sqrt(H.shape[1])\n    for _ in range(retrain_epochs):\n        for idx in torch.randperm(len(y), generator=g).split(256):\n            Mn = M / M.norm(dim=1, keepdim=True).clamp_min(1e-12)\n            Hb = H[idx].float()\n            if flip_p > 0:  # DependableHD-style noise injection: random query bit flips\n                Hb = torch.where(torch.rand(Hb.shape, generator=g) < flip_p, -Hb, Hb)\n            yb = y[idx]\n            S = (Hb @ Mn.T) * inv_sqrt_d\n            s_true = S.gather(1, yb[:, None]).squeeze(1)\n            S_other = S.scatter(1, yb[:, None], float("-inf"))\n            s_comp, comp = S_other.max(1)\n            hit = (s_true - s_comp) < margin if margin > 0 else (S.argmax(1) != yb)\n            if hit.any():\n                Hw = Hb[hit]\n                if adaptive:  # OnlineHD rule: C_y += lr(1-d_y)h, C_c -= lr(1-d_c)h, d = cosine\n                    wt = (1.0 - s_true[hit])[:, None]\n                    wc = (1.0 - s_comp[hit])[:, None]\n                    M.index_add_(0, yb[hit], lr * wt * Hw)\n                    M.index_add_(0, comp[hit], -lr * wc * Hw)\n                else:\n                    M.index_add_(0, yb[hit], lr * Hw)\n                    M.index_add_(0, comp[hit], -lr * Hw)\n    return M\n\n\nMARGIN_GRID = [0.0, 0.02, 0.04, 0.06, 0.09, 0.12, 0.16, 0.20, 0.25]\n\n\nLR_GRID = [0.01, 0.03, 0.1, 0.3]\n\n\ndef _val_split(n: int, seed: int, val_frac: float = 0.15, max_train: int = 20000):\n    """Held-out split of the training data for hyperparameter tuning. On large datasets the\n    tuning-train part is capped (default 20k samples) to keep the grid search affordable;\n    the final models are always trained on the full training set."""\n    perm = torch.randperm(n, generator=torch.Generator().manual_seed(seed + 99))\n    nv = int(n * val_frac)\n    return perm[nv:nv + max_train], perm[:nv]\n\n\n@torch.no_grad()\ndef tune_lr(H, y, n_classes, epochs, seed, grid=LR_GRID, **kw) -> float:\n    """Retraining step size chosen for plain perceptron retraining on a held-out split of\n    the training data; the same lr is then used by every retraining method (fair)."""\n    tr, va = _val_split(len(y), seed)\n    scores = [accuracy_digital(quantize(train_prototypes(H[tr], y[tr.numpy()], n_classes, epochs,\n                                                         lr=lr, seed=seed, **kw), "fp"),\n                               H[va], y[va.numpy()]) for lr in grid]\n    return grid[int(np.argmax(scores))]\n\n\n@torch.no_grad()\ndef tune_margin(H: torch.Tensor, y: np.ndarray, n_classes: int, epochs: int, seed: int,\n                lr: float = 0.05, precision: str = "fp", grid=MARGIN_GRID) -> float:\n    """Digital-optimal margin chosen on a held-out split of the *training* data (no test\n    data). This is the large-margin HDC baseline; the noise-aware method adds kappa*sigma."""\n    tr, va = _val_split(len(y), seed)\n    best, best_acc = 0.0, -1.0\n    for g in grid:\n        M = train_prototypes(H[tr], y[tr.numpy()], n_classes, epochs, lr=lr, seed=seed, margin=g)\n        acc = accuracy_digital(quantize(M, precision), H[va], y[va.numpy()])\n        if acc > best_acc + 1e-9:\n            best, best_acc = g, acc\n    return best\n\n\n@torch.no_grad()\ndef cosine_margins(Mq: torch.Tensor, H: torch.Tensor, y: np.ndarray, bs: int = 8192) -> np.ndarray:\n    """Signed margin of the true class over its strongest competitor, computed on the dot\n    products the crossbar uses and expressed in cosine units of the true-class prototype:\n    (h.m_true - max_{c != true} h.m_c) / (||m_true|| sqrt(D)). Equals the plain cosine margin\n    when all prototypes have the same norm."""\n    yt = torch.as_tensor(y)\n    nrm = Mq.norm(dim=1) * np.sqrt(H.shape[1])\n    out = []\n    for i in range(0, len(H), bs):\n        S = H[i:i + bs].float() @ Mq.T\n        yb = yt[i:i + bs]\n        st = S.gather(1, yb[:, None]).squeeze(1)\n        out.append((st - S.scatter(1, yb[:, None], float("-inf")).max(1).values) / nrm[yb])\n    return torch.cat(out).numpy()\n\n\n@torch.no_grad()\ndef predict_accuracy_gaussian(Mq: torch.Tensor, H: torch.Tensor, y: np.ndarray, sigma: float,\n                              n_draws: int = 20, seed: int = 0, bs: int = 8192) -> float:\n    """Margin-to-noise model: analog accuracy predicted from the *digital* scores of every\n    class plus Gaussian noise (sigma_hat from one calibration chip). No device simulation of\n    the test set is involved. The scores are the same dot products the crossbar computes,\n    s_c = h . m_c, and the noise on class c is sigma * ||m_c|| * sqrt(D), because sigma_hat is\n    measured in per-class cosine units. (Using cosines here would be wrong whenever the\n    quantised prototypes have unequal norms and the decisions are close.)"""\n    rng = np.random.default_rng(seed)\n    scale = (Mq.norm(dim=1) * np.sqrt(H.shape[1])).numpy()\n    correct = 0.0\n    for i in range(0, len(H), bs):\n        S = (H[i:i + bs].float() @ Mq.T).numpy()\n        yb = y[i:i + bs]\n        for _ in range(n_draws):\n            correct += ((S + rng.normal(0.0, 1.0, S.shape) * (sigma * scale)).argmax(1) == yb).sum()\n    return float(correct / (n_draws * len(H)))\n\n\n@torch.no_grad()\ndef similarity_noise_sigma_times(Mq: torch.Tensor, H_cal: torch.Tensor, rpu_config, times,\n                                 in_scale: float = 1.0, seed: int = 12345) -> list[float]:\n    """sigma_hat at every time of the grid, from one calibration chip programmed once."""\n    torch.manual_seed(seed)\n    layer = build_crossbar(Mq, rpu_config)\n    layer.program_analog_weights()\n    ref = H_cal.float() @ Mq.T\n    norm = Mq.norm(dim=1) * np.sqrt(H_cal.shape[1])\n    out = []\n    for t in times:\n        layer.drift_analog_weights(t)\n        A = layer(H_cal.float() * in_scale) / in_scale\n        out.append(((A - ref) / norm).std().item())\n    return out\n\n\n@torch.no_grad()\ndef similarity_noise_sigma(Mq: torch.Tensor, H_cal: torch.Tensor, rpu_config, t: float,\n                           in_scale: float = 1.0, seed: int = 12345) -> float:\n    """Std of the analog-minus-digital cosine similarity on calibration (training) queries,\n    from one independently programmed calibration chip."""\n    torch.manual_seed(seed)\n    layer = build_crossbar(Mq, rpu_config)\n    layer.program_analog_weights()\n    layer.drift_analog_weights(t)\n    A = layer(H_cal.float() * in_scale) / in_scale\n    ref = H_cal.float() @ Mq.T\n    norm = Mq.norm(dim=1) * np.sqrt(H_cal.shape[1])\n    return ((A - ref) / norm).std().item()\n\n\ndef quantize(M: torch.Tensor, precision: str, scale: str = "mse") -> torch.Tensor:\n    """Per-class L2 normalisation, then symmetric uniform quantisation to `precision`\n    (\'fp\', \'binary\', or \'Nbit\', N >= 2) with a per-class step size.\n\n    scale=\'mse\'    : step chosen per class to minimise the quantisation MSE (grid over\n                     clipping ratios 2%..100% of max|w|); values beyond the clip saturate.\n    scale=\'maxabs\' : step = max|w| / levels (no clipping; wastes levels when a few\n                     entries are large, which is what made 2 bit worse than 1 bit)."""\n    M = M / M.norm(dim=1, keepdim=True).clamp_min(1e-12)\n    if precision == "fp":\n        return M\n    if precision == "binary":\n        return torch.where(M >= 0, 1.0, -1.0)\n    bits = int(precision.removesuffix("bit"))\n    levels = 2 ** (bits - 1) - 1  # e.g. 4 bit -> integers in [-7, 7]\n    amax = M.abs().amax(dim=1, keepdim=True).clamp_min(1e-12)\n    if scale == "maxabs":\n        st = amax / levels\n        return torch.round(M / st) * st\n    ratios = torch.linspace(0.02, 1.0, 50)\n    best_err = torch.full((M.shape[0], 1), float("inf"))\n    best_st = amax / levels\n    for r in ratios:\n        st = r * amax / levels\n        q = torch.clamp(torch.round(M / st), -levels, levels) * st\n        err = ((q - M) ** 2).sum(dim=1, keepdim=True)\n        better = err < best_err\n        best_err = torch.where(better, err, best_err)\n        best_st = torch.where(better, st, best_st)\n    return torch.clamp(torch.round(M / best_st), -levels, levels) * best_st\n\n\n@torch.no_grad()\ndef accuracy_digital(M: torch.Tensor, H: torch.Tensor, y: np.ndarray, bs: int = 8192) -> float:\n    pred = torch.cat([(H[i:i + bs].float() @ M.T).argmax(1) for i in range(0, len(H), bs)])\n    return (pred.numpy() == y).mean().item()\n\n\n# ----------------------------------------------------------------------------- crossbar\nDEVICES = ["pcm", "reram_wan", "reram_cmo"]\n# Times after programming (s). The NeuRRAM ReRAM model only has published coefficients\n# at 1 s, 1 day and 2 days, so it is never extrapolated; 1 s / 1 day / 2 days are shared\n# by all devices for like-for-like comparison. CMO drift is a log(t) fit (extrapolated\n# beyond its characterisation window at 30 days / 1 year; reported as such).\nT_GRID = {\n    "pcm": [1.0, 3600.0, 86400.0, 172800.0, 2592000.0, 31536000.0],\n    "reram_cmo": [1.0, 3600.0, 86400.0, 172800.0, 2592000.0, 31536000.0],\n    "reram_wan": [1.0, 86400.0, 172800.0],\n}\n\n\ndef _safe_cmo_model(**kw):\n    """AIHWKit\'s CMO/HfOx model takes log10 of the drifted conductance before clamping it,\n    so when scaled-up noise pushes a device below 0 S the read-noise term becomes NaN and\n    poisons the whole column. Clamp to the physical floor g_min first (identical to the\n    original whenever the conductance stays positive, i.e. at nominal noise)."""\n    from math import log, sqrt\n\n    from aihwkit.inference import ReRamCMONoiseModel\n    from torch import randn_like\n\n    class SafeReRamCMONoiseModel(ReRamCMONoiseModel):\n        @torch.no_grad()\n        def apply_drift_noise_to_conductance(self, g_prog, drift_noise_param, t_inference):\n            if t_inference == 0:\n                return g_prog\n            g_mean = g_prog + (self.decay_dict["mean"][0] * log(t_inference) * self.drift_scale)\n            sig_rel = self.decay_dict["std"][0] * log(t_inference) + self.decay_dict["std"][1]\n            g_drift = g_mean + randn_like(g_prog) * sig_rel * self.drift_scale\n            g_drift = g_drift.clamp(min=self.g_min, max=self.g_max)\n            sig_read = (self.read_dict["K"] * torch.log10(g_drift) *\n                        sqrt(log((t_inference + self.read_dict["t_read"]) /\n                                 (2 * self.read_dict["t_read"]))))\n            g_final = g_drift + sig_read * randn_like(g_prog) * self.read_noise_scale\n            return g_final.clamp(min=self.g_min, max=self.g_max)\n\n    return SafeReRamCMONoiseModel(**kw)\n\n\ndef make_inference_config(device: str, periphery: str = "realistic", drift_comp: bool = True,\n                          noise_scale: float = 1.0):\n    from aihwkit.inference import (GlobalDriftCompensation, PCMLikeNoiseModel,\n                                   ReRamCMONoiseModel, ReRamWan2022NoiseModel)\n    from aihwkit.simulator.configs import InferenceRPUConfig\n\n    cfg = InferenceRPUConfig()\n    if device == "pcm":\n        cfg.noise_model = PCMLikeNoiseModel(g_max=25.0, prog_noise_scale=noise_scale,\n                                            read_noise_scale=noise_scale, drift_scale=noise_scale)\n    elif device == "reram_wan":\n        cfg.noise_model = ReRamWan2022NoiseModel(noise_scale=noise_scale)\n    elif device == "reram_cmo":\n        cfg.noise_model = _safe_cmo_model(prog_noise_scale=noise_scale,\n                                          read_noise_scale=noise_scale, drift_scale=noise_scale)\n    else:\n        raise ValueError(device)\n    from aihwkit.simulator.parameters.enums import BoundManagementType, NoiseManagementType\n\n    # each tile\'s weights span the full conductance range (max |w| -> g_max), so every\n    # precision gets the same signal current per device; outputs are rescaled digitally\n    cfg.mapping.weight_scaling_omega = 1.0\n    cfg.mapping.weight_scaling_columnwise = False\n    if periphery == "ideal":       # isolate the device: no DAC/ADC quantisation, no IO noise\n        cfg.forward.is_perfect = True\n    elif periphery == "realistic":\n        # single-shot read with a fixed, pre-calibrated ADC range (see calibrate_input_scale):\n        # 7-bit DAC, 9-bit ADC, output noise as in AIHWKit defaults; no dynamic input\n        # re-normalisation and no iterative re-reads, which a real macro would not do per query\n        cfg.forward.noise_management = NoiseManagementType.NONE\n        cfg.forward.bound_management = BoundManagementType.NONE\n    else:\n        raise ValueError(periphery)\n    cfg.drift_compensation = GlobalDriftCompensation() if drift_comp else None\n    return cfg\n\n\n@torch.no_grad()\ndef calibrate_input_scale(Mq: torch.Tensor, H_cal: torch.Tensor, out_bound: float = 12.0,\n                          max_input_size: int = 512, pct: float = 99.9) -> float:\n    """Read-voltage scale s so that the `pct` percentile of |tile partial sums| on\n    calibration queries lands at the ADC full scale. Done once per programmed model on\n    training data (never on test data), like an ADC range calibration on a real chip."""\n    vals = []\n    for r0 in range(0, Mq.shape[1], max_input_size):\n        W = Mq[:, r0:r0 + max_input_size]\n        W = W / W.abs().max().clamp_min(1e-12)\n        vals.append((H_cal[:, r0:r0 + max_input_size].float() @ W.T).abs().flatten())\n    p = torch.quantile(torch.cat(vals)[:2_000_000], pct / 100.0).item()\n    return min(1.0, out_bound / max(p, 1e-12))\n\n\ndef build_crossbar(Mq: torch.Tensor, rpu_config):\n    from aihwkit.nn import AnalogLinear\n    C, D = Mq.shape\n    layer = AnalogLinear(D, C, bias=False, rpu_config=rpu_config)\n    layer.set_weights(Mq.clone(), None)\n    layer.eval()\n    return layer\n\n\n@torch.no_grad()\ndef accuracy_crossbar(Mq, H, y, rpu_config, times, n_chips: int = 10, seed: int = 0,\n                      bs: int = 2048, in_scale: float = 1.0, ref_t: float | None = None,\n                      return_preds: bool = False):\n    """acc[chip, t]: each chip is an independent programming of the same prototypes.\n    Queries are applied as +/- in_scale (read-voltage scaling from the ADC calibration).\n    With return_preds, also returns predictions[chip, sample] at time ref_t."""\n    acc = np.zeros((n_chips, len(times)))\n    preds_ref = np.zeros((n_chips, len(H)), dtype=np.int16) if return_preds else None\n    for c in range(n_chips):\n        torch.manual_seed(seed * 1000 + c)\n        layer = build_crossbar(Mq, rpu_config)\n        layer.program_analog_weights()\n        for k, t in enumerate(times):\n            layer.drift_analog_weights(t)\n            outs = [layer(H[i:i + bs].float() * in_scale) for i in range(0, len(H), bs)]\n            if any(not torch.isfinite(o).all() for o in outs):\n                raise FloatingPointError(f"non-finite crossbar output at t={t} (chip {c})")\n            pred = torch.cat([o.argmax(1) for o in outs])\n            acc[c, k] = (pred.numpy() == y).mean()\n            if return_preds and t == ref_t:\n                preds_ref[c] = pred.numpy()\n    return (acc, preds_ref) if return_preds else acc\n\n\ndef encoder_input_scale(enc: Encoder, X_cal: np.ndarray) -> float:\n    """ADC range calibration of the encoder crossbar on training inputs."""\n    return calibrate_input_scale(enc.P.T.contiguous(), enc.pre(X_cal))\n\n\n@torch.no_grad()\ndef accuracy_end_to_end(enc: Encoder, Mq, X, y, rpu_config, times, n_chips: int = 10,\n                        seed: int = 0, in_scale_am: float = 1.0, in_scale_enc: float = 1.0,\n                        bs: int = 2048):\n    """End-to-end analog HDC. Per chip, the projection matrix P and the prototypes are\n    programmed into two crossbars of the same technology; both drift together. The encoder\n    crossbar computes z = pre(x) P in analog (features as DAC voltages), the digital\n    periphery applies the encoder non-linearity / sign, and the bipolar query drives the\n    prototype crossbar. Returns acc[chip, t] and the query bit-flip rate[chip, t] relative\n    to digital encoding."""\n    if not hasattr(enc, "P"):\n        raise ValueError("end-to-end analog encoding needs a projection encoder (rp/nonlinear)")\n    Xp = enc.pre(X)\n    H_dig = enc(X)\n    acc = np.zeros((n_chips, len(times)))\n    flips = np.zeros((n_chips, len(times)))\n    for c in range(n_chips):\n        torch.manual_seed(seed * 1000 + 500 + c)\n        el = build_crossbar(enc.P.T.contiguous(), rpu_config)\n        el.program_analog_weights()\n        torch.manual_seed(seed * 1000 + c)\n        am = build_crossbar(Mq, rpu_config)\n        am.program_analog_weights()\n        for k, t in enumerate(times):\n            el.drift_analog_weights(t)\n            am.drift_analog_weights(t)\n            preds, nflip = [], 0\n            for i in range(0, len(Xp), bs):\n                z = el(Xp[i:i + bs] * in_scale_enc)\n                h = enc.post(z)\n                nflip += (h != H_dig[i:i + bs]).sum().item()\n                o = am(h.float() * in_scale_am)\n                if not (torch.isfinite(z).all() and torch.isfinite(o).all()):\n                    raise FloatingPointError(f"non-finite output at t={t} (chip {c})")\n                preds.append(o.argmax(1))\n            acc[c, k] = (torch.cat(preds).numpy() == y).mean()\n            flips[c, k] = nflip / H_dig.numel()\n    return acc, flips\n\n\n@dataclass\nclass HDCModel:\n    encoder: Encoder\n    prototypes: torch.Tensor  # float, unnormalised\n    n_classes: int\n', 'analytic.py': '"""Closed-form (simulation-free) accuracy model for HDC prototypes in an analog crossbar.\n\nOnly single-device statistics enter: for a device technology and a read time t we measure,\nonce, how a weight w (normalised to the tile\'s largest |w|, as the crossbar mapping does)\nis perturbed by programming noise, drift and read noise:\n\n    m_t(w) = E[w_tilde(t)],   v_t(w) = Var[w_tilde(t)]        (device characterisation)\n\nGlobal drift compensation divides every tile output by alpha_t, which we compute exactly as\nAIHWKit does (mean |output| of one-hot reads now vs. right after programming).\n\nFor a query h in {-1,+1}^D the analog score of class c is a sum over tiles T (512 rows each):\n\n    s_c = sum_T A_T * [ sum_{j in T} h_j * w_tilde_cj / alpha_T  +  n_T,c / s ]\n\nwith A_T the tile\'s weight scale, s the read-voltage (input) scale and n_T,c ~ N(0, sigma_out^2)\nthe per-tile output noise. Taking expectations gives a deterministic, chip-independent\ndistortion of every prototype entry and a Gaussian score noise with per-class variance\n\n    mean:  mu_cj = A_T * m_t(w_cj) / alpha_T\n    var :  V_c   = sum_T A_T^2 * [ sum_{j in T} v_t(w_cj) / alpha_T^2  +  sigma_out^2 / s^2 ]\n\n(the h_j^2 = 1 factor makes V_c query independent). Errors of different devices are\nindependent, so the noise on the decision variable s_true - s_comp has variance\nV_true + V_comp: this is sigma_Delta in closed form. ADC quantisation is deterministic and\nnearly identical for nearly equal scores, so it does not enter sigma_Delta.\n\nThe predicted accuracy is the probability that argmax_c (mu-distorted score + N(0, V_c))\nreturns the true class, estimated by drawing the Gaussian part only (no device simulation).\n"""\nfrom __future__ import annotations\n\nimport functools\n\nimport numpy as np\nimport torch\n\nGRID = np.linspace(-1.0, 1.0, 81)\n\n\n@functools.lru_cache(maxsize=64)\ndef characterise(device: str, t: float, noise_scale: float = 1.0, n_rep: int = 4000,\n                 seed: int = 0):\n    """Single-device statistics m_t(w), v_t(w) on GRID and m_0(w) (right after programming).\n    Uses the same noise model object AIHWKit uses inside the tile."""\n    from hdc import make_inference_config\n\n    cfg = make_inference_config(device, "ideal", noise_scale=noise_scale)\n    nm = cfg.noise_model\n    torch.manual_seed(seed)\n    W = torch.tensor(GRID, dtype=torch.float32).repeat(n_rep, 1)  # max |w| = 1 per row block\n    prog, params = nm.apply_programming_noise(W)\n    W0 = prog  # AIHWKit takes the drift baseline right after programming\n    Wt = nm.apply_drift_noise(prog, params, t)\n    return (Wt.mean(0).numpy().astype(np.float64), Wt.var(0).numpy().astype(np.float64),\n            W0.mean(0).numpy().astype(np.float64))\n\n\ndef _interp(fn_vals, w):\n    return np.interp(w, GRID, fn_vals)\n\n\ndef score_model(Mq: torch.Tensor, device: str, t: float, in_scale: float, periphery: str,\n                noise_scale: float = 1.0, max_input_size: int = 512, out_noise: float = 0.06):\n    """Returns (M_eff, V): drift-distorted prototypes (C x D, raw units) and the per-class\n    score-noise variance V (C,) in raw dot-product units."""\n    m_t, v_t, m_0 = characterise(device, float(t), float(noise_scale))\n    M = Mq.numpy().astype(np.float64)\n    C, D = M.shape\n    M_eff = np.zeros_like(M)\n    V = np.zeros(C)\n    sig_out = 0.0 if periphery == "ideal" else out_noise\n    s = in_scale if periphery == "realistic" else 1.0\n    for r0 in range(0, D, max_input_size):\n        blk = M[:, r0:r0 + max_input_size]\n        A = np.abs(blk).max()\n        if A == 0:\n            continue\n        w = blk / A\n        mt, vt, m0 = _interp(m_t, w), _interp(v_t, w), _interp(m_0, w)\n        # AIHWKit global compensation: mean |one-hot readout| now / right after programming\n        alpha = np.abs(mt).mean() / max(np.abs(m0).mean(), 1e-12)\n        M_eff[:, r0:r0 + max_input_size] = A * mt / alpha\n        V += A ** 2 * (vt.sum(1) / alpha ** 2 + sig_out ** 2 / s ** 2)\n    return M_eff, V\n\n\n@torch.no_grad()\ndef predict_accuracy_analytic(Mq, H, y, device, t, in_scale, periphery="realistic",\n                              noise_scale=1.0, n_draws=20, seed=0, bs=8192):\n    M_eff, V = score_model(Mq, device, t, in_scale, periphery, noise_scale)\n    Me = torch.tensor(M_eff, dtype=torch.float32)\n    sd = np.sqrt(V)\n    rng = np.random.default_rng(seed)\n    correct = 0\n    for i in range(0, len(H), bs):\n        S = (H[i:i + bs].float() @ Me.T).numpy()\n        yb = y[i:i + bs]\n        for _ in range(n_draws):\n            correct += ((S + rng.normal(0, 1, S.shape) * sd).argmax(1) == yb).sum()\n    return float(correct / (n_draws * len(H)))\n\n\ndef sigma_delta_analytic(Mq, H_cal, y_cal, device, t, in_scale, periphery="realistic",\n                         noise_scale=1.0):\n    """sigma_Delta in the cosine units used by the calibration-chip estimate, for comparison."""\n    _, V = score_model(Mq, device, t, in_scale, periphery, noise_scale)\n    M = Mq.numpy()\n    norm = np.linalg.norm(M, axis=1) * np.sqrt(M.shape[1])\n    R = (H_cal.float().numpy() @ M.T) / norm\n    C = M.shape[0]\n    comp = np.where(np.arange(C)[None, :] == y_cal[:, None], -np.inf, R).argmax(1)\n    # per-sample variance of (e_true - e_comp) in cosine units, averaged\n    var = V[y_cal] / norm[y_cal] ** 2 + V[comp] / norm[comp] ** 2\n    return float(np.sqrt(var.mean()))\n\n\n# --------------------------------------------------------------------------------------\n# v2: periphery-aware closed form. The tile output is formed in the *analog* domain as\n#   u_T = s_eff * h_T . w_tilde_T + n_T          (n_T ~ N(0, sigma_out^2))\n# and is then clipped to +-out_bound and rounded to the ADC step BEFORE the digital\n# rescale A_T / (s * alpha_T). Two deterministic periphery effects therefore matter when the\n# read scale s is small (large common-mode partial sums sitting near the ADC bound):\n#   * DAC quantisation: s is realised as s_eff = round(s / inp_step) * inp_step,\n#   * read-time conductance gain (the largest programmed weight of the tile, about 1.1 for 512-row tiles of the Wan-2022 ReRAM) which\n#     drift compensation only removes AFTER the ADC.\n# Both push partial sums past the calibrated bound; clipping then removes class differences\n# (ties) and cannot be captured by a Gaussian score model. v2 keeps the per-device closed\n# form (mean m_t, variance v_t; CLT over the 512 rows of a tile) but evaluates\n# clip + ADC rounding per tile on Gaussian draws. Still no device simulation.\n# --------------------------------------------------------------------------------------\nOUT_BOUND = 12.0\nOUT_STEP = 2 * OUT_BOUND / (2 ** 9 - 2)   # 9-bit ADC (AIHWKit default out_res)\nINP_STEP = 2.0 / (2 ** 7 - 2)             # 7-bit DAC on [-1, 1] (AIHWKit default inp_res)\n\n\ndef dac_scale(s: float) -> float:\n    return float(np.round(s / INP_STEP) * INP_STEP)\n\n\n# Devices whose AIHWKit drift step re-derives conductances from the *original* targets but\n# converts back with the scale of the *programmed* weights: every tile then reads with a\n# chip-random gain G_T = max_j |w_prog,j| (the largest programmed weight of that tile),\n# e.g. ~1.1 for the Wan-2022 ReRAM model. PCM / CMO re-use the programmed conductances, G = 1.\nPROG_MAX_GAIN = {"reram_wan": True, "pcm": False, "reram_cmo": False}\n\n\n@functools.lru_cache(maxsize=64)\ndef characterise2(device: str, t: float, noise_scale: float = 1.0, n_rep: int = 4000,\n                  seed: int = 0):\n    """Like characterise, but returns intrinsic statistics with the programming-max gain of\n    the characterisation tensor divided out, plus the programming variance v_0(w)."""\n    from hdc import make_inference_config\n\n    nm = make_inference_config(device, "ideal", noise_scale=noise_scale).noise_model\n    torch.manual_seed(seed)\n    W = torch.tensor(GRID, dtype=torch.float32).repeat(n_rep, 1)\n    prog, params = nm.apply_programming_noise(W)\n    Wt = nm.apply_drift_noise(prog, params, t)\n    if PROG_MAX_GAIN[device]:\n        Wt = Wt / prog.abs().max()\n    f = lambda a: a.numpy().astype(np.float64)\n    return f(Wt.mean(0)), f(Wt.var(0)), f(prog.mean(0)), f(prog.var(0))\n\n\n_XG = np.linspace(0.8, 2.0, 1201)\n\n\ndef gain_quantiles(w: np.ndarray, m0: np.ndarray, v0: np.ndarray, n_q: int = 64):\n    """Quantiles of G = max_j |X_j|, X_j ~ N(m0(w_j), v0(w_j)) independent (exact CDF\n    as a product of single-device CDFs; only entries that can reach the max matter)."""\n    from scipy.stats import norm\n    sel = np.abs(w).ravel() > 0.6\n    mu, sd = np.abs(m0.ravel()[sel]), np.sqrt(v0.ravel()[sel]) + 1e-9\n    logF = np.zeros_like(_XG)\n    for k in range(0, len(mu), 4096):\n        a, b = mu[k:k + 4096, None], sd[k:k + 4096, None]\n        p = norm.cdf((_XG[None] - a) / b) - norm.cdf((-_XG[None] - a) / b)\n        logF += np.log(np.clip(p, 1e-300, 1)).sum(0)\n    F = np.exp(logF)\n    q = (np.arange(n_q) + 0.5) / n_q\n    return np.interp(q, F, _XG)\n\n\ndef tile_model(Mq: torch.Tensor, device: str, t: float, noise_scale: float = 1.0,\n               max_input_size: int = 512):\n    """Per tile: (row slice, A_T, alpha_T, intrinsic mean m (C x rows), summed intrinsic\n    variance per class (C,), quantiles of the read gain G_T)."""\n    m_t, v_t, m_0, v_0 = characterise2(device, float(t), float(noise_scale))\n    M = Mq.numpy().astype(np.float64)\n    out = []\n    for r0 in range(0, M.shape[1], max_input_size):\n        blk = M[:, r0:r0 + max_input_size]\n        A = np.abs(blk).max()\n        if A == 0:\n            continue\n        w = blk / A\n        mt, vt, m0 = _interp(m_t, w), _interp(v_t, w), _interp(m_0, w)\n        if PROG_MAX_GAIN[device]:\n            G = gain_quantiles(w, m0, _interp(v_0, w))\n        else:\n            G = np.ones(1)\n        # drift compensation divides by mean|read| / mean|programmed|; G_T cancels exactly\n        alpha = np.abs(mt).mean() / max(np.abs(m0).mean(), 1e-12)\n        out.append((slice(r0, r0 + max_input_size), A, alpha, mt, vt.sum(1), G))\n    return out\n\n\n@torch.no_grad()\ndef predict_accuracy_analytic2(Mq, H, y, device, t, in_scale, periphery="realistic",\n                               noise_scale=1.0, n_draws=20, seed=0, bs=4096,\n                               out_noise=0.06, return_parts=False, ablate=()):\n    """ablate: any of "dac", "gain", "clip" switches that v2 effect off (component ablation):\n    dac -> unquantised read scale, gain -> per-tile read gain fixed at 1,\n    clip -> no per-tile ADC clipping/rounding (output noise kept)."""\n    if periphery != "realistic":\n        return predict_accuracy_analytic(Mq, H, y, device, t, in_scale, periphery,\n                                         noise_scale, n_draws, seed)\n    tiles = tile_model(Mq, device, t, noise_scale)\n    s, se = float(in_scale), dac_scale(in_scale)\n    if "dac" in ablate:\n        se = s\n    rng = np.random.default_rng(seed)\n    correct = 0\n    clip_frac = 0.0\n    n_out = 0\n    for i in range(0, len(H), bs):\n        Hb = H[i:i + bs].float().numpy().astype(np.float64)\n        yb = y[i:i + bs]\n        U = [(se * (Hb[:, sl] @ mt.T), se ** 2 * vs, A / (s * al), G)\n             for sl, A, al, mt, vs, G in tiles]\n        for _ in range(n_draws):\n            S = 0.0\n            for mu, var, g, G in U:\n                Gc = 1.0 if "gain" in ablate else G[rng.integers(len(G))]  # one read gain per tile\n                u = Gc * mu + rng.standard_normal(mu.shape) * np.sqrt(Gc ** 2 * var + out_noise ** 2)\n                clip_frac += (np.abs(u) >= OUT_BOUND).sum()\n                n_out += u.size\n                if "clip" not in ablate:\n                    u = np.round(np.clip(u, -OUT_BOUND, OUT_BOUND) / OUT_STEP) * OUT_STEP\n                S = S + g * u / Gc\n            # ties (several classes clipped to the same value) resolve to the lowest index,\n            # as torch.argmax does in the crossbar evaluation\n            correct += (S.argmax(1) == yb).sum()\n    acc = float(correct / (n_draws * len(H)))\n    return (acc, clip_frac / max(n_out, 1)) if return_parts else acc\n', 'sweep_hdc2.py': '"""Experiment driver v2 for the HDC-on-memristive-crossbars study.\n\nA job = (stage, dataset, encoder, D, encoder seed, centring). It encodes once, tunes the\nretraining step size and the digital-optimal margin on a validation split of the training\ndata, trains every requested method, and evaluates each method x precision x device x\nnoise scale x periphery over n_chips independently programmed chips and the device\'s\ntime grid. Besides accuracy it logs, at the 1-day reference time, the margin-to-noise\nstatistics needed to test the flip law: the share of correctly classified test samples in\nbins of (digital cosine margin / sigma_hat) and the analog-vs-digital decision flip rate in\neach bin, a fine histogram of margin / sigma_hat, sigma_hat at every time of the grid, and\nthe accuracy predicted by the margin-to-noise model (digital scores + Gaussian noise of std\nsigma_hat) at every time. One jsonl line per evaluated combination; finished jobs are skipped\n(resumable).\n\nTraining methods (all retraining methods share the tuned lr and the same epoch budget):\n  single        one-pass bundling (no retraining)\n  perceptron    classic HDC retraining (update on misclassification)\n  onlinehd      OnlineHD adaptive retraining (similarity-weighted updates)\n  largemargin   margin retraining with the digital-optimal margin (MM-HDC-style baseline)\n  dependable    digital-optimal margin + random query bit flips (p=0.05) during training\n                (DependableHD-style baseline)\n  noisecal      margin = digital-optimal + KAPPA * sigma_hat, sigma_hat measured on one\n                calibration chip with training data (noise-calibrated variant)\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport itertools\nimport json\nimport os\nimport time\nfrom concurrent.futures import ProcessPoolExecutor, as_completed\nfrom pathlib import Path\n\nALL_METHODS = ["single", "perceptron", "onlinehd", "largemargin", "dependable", "noisecal"]\nDATASETS7 = "isolet,ucihar,mnist,fmnist,letter,pendigits,satimage"\nKAPPA = 2.0          # fixed a priori from the pilot study, never tuned on test data\nEPOCHS = 20\nREF_T = 86400.0      # 1 day: reference time for sigma_hat and the flip-law statistics\nFLIP_P = 0.05\nBINS = [0.0, 0.5, 1.0, 2.0, 3.0, 4.0, 6.0, float("inf")]  # margin / sigma_hat\nHIST_EDGES = [-1e9] + [round(-6 + 0.25 * k, 2) for k in range(73)] + [1e9]  # -6..12 sigma\n\nSTAGES = {\n    # core benchmark: everything that the main figures and the flip law need\n    "core": dict(datasets=DATASETS7, encoders="rp,nonlinear", dims="256,512,1024,2048,4096,8192",\n                 seeds="0,1,2,3,4", center="1", methods=",".join(ALL_METHODS),\n                 precisions="fp,4bit,binary", devices="pcm,reram_wan,reram_cmo",\n                 noise="1.0", peripheries="realistic", e2e="0", n_chips=8),\n    # third encoder family\n    "encoders": dict(datasets=DATASETS7, encoders="idlevel", dims="512,2048,8192", seeds="0,1,2",\n                     center="1", methods="perceptron,largemargin,dependable,noisecal",\n                     precisions="4bit", devices="pcm,reram_wan,reram_cmo", noise="1.0",\n                     peripheries="realistic", e2e="0", n_chips=8),\n    # encoder in the crossbar too\n    "e2e": dict(datasets=DATASETS7, encoders="rp,nonlinear", dims="512,2048,8192", seeds="0,1,2",\n                center="1", methods="perceptron,largemargin,noisecal", precisions="4bit",\n                devices="pcm,reram_wan,reram_cmo", noise="1.0", peripheries="realistic",\n                e2e="1", n_chips=6),\n    # end-to-end with a bipolar (+/-1) projection matrix (fix for drift-induced encoder flips)\n    "e2e_bipolar": dict(datasets=DATASETS7, encoders="rp_bipolar", dims="512,2048,8192",\n                        seeds="0,1,2", center="1", methods="largemargin", precisions="4bit",\n                        devices="pcm,reram_wan,reram_cmo", noise="1.0", peripheries="realistic",\n                        e2e="1", n_chips=6),\n    # device-noise stress and centring ablation\n    "stress": dict(datasets=DATASETS7, encoders="rp", dims="256,1024,4096", seeds="0,1,2",\n                   center="0,1", methods="perceptron,largemargin,dependable,noisecal",\n                   precisions="4bit,binary", devices="pcm,reram_wan,reram_cmo",\n                   noise="0.5,1.0,2.0,4.0,8.0", peripheries="realistic", e2e="0", n_chips=6),\n    # classic HDC benchmark: European language recognition with character trigrams\n    # (Karunaratne et al. 2020 and Huang et al. 2026 run this task on PCM / ReRAM chips)\n    "langid": dict(datasets="langid", encoders="ngram", dims="512,1024,2048", seeds="0,1,2",\n                   center="0", methods=",".join(ALL_METHODS), precisions="fp,4bit,binary",\n                   devices="pcm,reram_wan,reram_cmo", noise="1.0", peripheries="realistic",\n                   e2e="0", n_chips=8),\n    # 2-bit cells and the ideal-periphery reference\n    "precision": dict(datasets=DATASETS7, encoders="rp", dims="256,1024,4096", seeds="0,1,2",\n                      center="1", methods="perceptron,largemargin,noisecal",\n                      precisions="fp,4bit,2bit,binary", devices="pcm,reram_wan,reram_cmo",\n                      noise="1.0", peripheries="ideal,realistic", e2e="0", n_chips=6),\n}\n\n# shorter time grid than v1 (drops 1 h) to save compute; 1 s / 1 d / 2 d shared by all\nTIMES = {"pcm": [1.0, 86400.0, 172800.0, 2592000.0, 31536000.0],\n         "reram_cmo": [1.0, 86400.0, 172800.0, 2592000.0, 31536000.0],\n         "reram_wan": [1.0, 86400.0, 172800.0]}\n\n\ndef job_key(j: dict) -> str:\n    return hashlib.md5(json.dumps({k: v for k, v in j.items() if k != "data_home"},\n                                  sort_keys=True).encode()).hexdigest()\n\n\ndef done_keys(path: Path) -> set:\n    if not path.exists():\n        return set()\n    keys = set()\n    for l in path.read_text().splitlines():\n        if l.strip():\n            try:\n                keys.add(json.loads(l)["job_key"])\n            except json.JSONDecodeError:  # a line cut off by a disconnect\n                pass\n    return keys\n\n\n_DATA: dict = {}\n\n\ndef _flip_stats(margins, dig_pred, y, preds_ref, sigma):\n    """Share of correct samples per margin/sigma bin and the mean analog flip rate there."""\n    import numpy as np\n    correct = dig_pred == y\n    r = margins[correct] / max(sigma, 1e-12)\n    flips = (preds_ref[:, correct] != dig_pred[correct][None, :]).mean(0)\n    b = np.digitize(r, BINS[1:-1])\n    share = [float(np.mean(b == k)) for k in range(len(BINS) - 1)]\n    rate = [float(flips[b == k].mean()) if (b == k).any() else None for k in range(len(BINS) - 1)]\n    return share, rate, [float(q) for q in np.quantile(margins, [0.05, 0.25, 0.5, 0.75, 0.95])]\n\n\ndef _worker(j: dict) -> list[dict]:\n    os.environ.setdefault("OMP_NUM_THREADS", "1")\n    import numpy as np\n    import torch\n    torch.set_num_threads(int(os.environ.get("HDC_THREADS", "1")))\n    from hdc import (accuracy_crossbar, accuracy_digital, accuracy_end_to_end,\n                     calibrate_input_scale, cosine_margins, encoder_input_scale, load_dataset,\n                     make_encoder, make_inference_config, predict_accuracy_gaussian, quantize,\n                     similarity_noise_sigma, similarity_noise_sigma_times, train_prototypes,\n                     tune_lr, tune_margin)\n\n    t0 = time.time()\n    if j["dataset"] not in _DATA:\n        _DATA.clear()\n        _DATA[j["dataset"]] = load_dataset(j["dataset"], j["data_home"])\n    Xtr, ytr, Xte, yte, C = _DATA[j["dataset"]]\n    enc = make_encoder(j["encoder"], Xtr.shape[1], j["dim"], j["seed"], Xtr, center=j["center"])\n    Htr, Hte = enc(Xtr), enc(Xte)\n    g = torch.Generator().manual_seed(1)\n    cal_idx = torch.randperm(len(Htr), generator=g)[:5000]\n    H_cal = Htr[cal_idx]\n    lr = tune_lr(Htr, ytr, C, EPOCHS, j["seed"])\n    g_dig = tune_margin(Htr, ytr, C, EPOCHS, j["seed"], lr=lr)\n    meth = j["methods"]\n    base = {}\n    if "single" in meth:\n        base["single"] = train_prototypes(Htr, ytr, C, 0, seed=j["seed"])\n    if "perceptron" in meth or "noisecal" in meth:\n        base["perceptron"] = train_prototypes(Htr, ytr, C, EPOCHS, lr=lr, seed=j["seed"])\n    if "onlinehd" in meth:\n        base["onlinehd"] = train_prototypes(Htr, ytr, C, EPOCHS, lr=lr, seed=j["seed"], adaptive=True)\n    if "largemargin" in meth:\n        base["largemargin"] = train_prototypes(Htr, ytr, C, EPOCHS, lr=lr, seed=j["seed"], margin=g_dig)\n    if "dependable" in meth:\n        base["dependable"] = train_prototypes(Htr, ytr, C, EPOCHS, lr=lr, seed=j["seed"],\n                                              margin=g_dig, flip_p=FLIP_P)\n    s_enc = encoder_input_scale(enc, Xtr[cal_idx.numpy()]) if j["e2e"] else None\n    t_train = time.time() - t0\n\n    out = []\n    for prec, dev, ns, per in itertools.product(j["precisions"], j["devices"], j["noise"],\n                                                j["peripheries"]):\n        cfg = make_inference_config(dev, per, noise_scale=ns)\n        times = TIMES[dev]\n        models = {m: base[m] for m in meth if m in base}\n        sig_p = None\n        if "noisecal" in meth:  # sigma_hat on a calibration chip, training data only\n            Mp = quantize(base["perceptron"], prec)\n            sp = calibrate_input_scale(Mp, H_cal) if per == "realistic" else 1.0\n            sig_p = similarity_noise_sigma(Mp, H_cal, cfg, REF_T, sp)\n            models["noisecal"] = train_prototypes(Htr, ytr, C, EPOCHS, lr=lr, seed=j["seed"],\n                                                  margin=g_dig + KAPPA * sig_p)\n        for m in meth:\n            Mq = quantize(models[m], prec)\n            s = calibrate_input_scale(Mq, H_cal) if per == "realistic" else 1.0\n            dig = accuracy_digital(Mq, Hte, yte)\n            rec = {"job_key": j["job_key"], "stage": j["stage"], "dataset": j["dataset"],\n                   "n_classes": C, "encoder": j["encoder"], "dim": j["dim"], "seed": j["seed"],\n                   "center": j["center"], "e2e": j["e2e"], "method": m, "precision": prec,\n                   "device": dev, "noise_scale": ns, "periphery": per, "lr": lr,\n                   "margin_dig": g_dig, "sigma_cal_perceptron": sig_p,\n                   "margin_used": (g_dig + KAPPA * sig_p) if m == "noisecal" else\n                                  (g_dig if m in ("largemargin", "dependable") else 0.0),\n                   "in_scale": s, "digital_acc": dig, "times": times}\n            if j["e2e"]:\n                acc, flips = accuracy_end_to_end(enc, Mq, Xte, yte, cfg, times, j["n_chips"],\n                                                 seed=j["seed"], in_scale_am=s, in_scale_enc=s_enc)\n                rec["query_bitflip_mean"] = flips.mean(0).tolist()\n            else:\n                acc, preds = accuracy_crossbar(Mq, Hte, yte, cfg, times, j["n_chips"],\n                                               seed=j["seed"], in_scale=s, ref_t=REF_T,\n                                               return_preds=True)\n                sig_t = similarity_noise_sigma_times(Mq, H_cal, cfg, times, s)\n                sig = sig_t[times.index(REF_T)]\n                margins = cosine_margins(Mq, Hte, yte)\n                # margin-to-noise model: predicted accuracy at every time, no test-set device sim\n                rec["sigma_hat_t"] = sig_t\n                rec["pred_acc_t"] = [predict_accuracy_gaussian(Mq, Hte, yte, st, seed=j["seed"])\n                                     for st in sig_t]\n                hist, _ = np.histogram(margins / max(sig, 1e-12), bins=HIST_EDGES)\n                rec["margin_hist_sigma_units"] = (hist / len(margins)).round(6).tolist()\n                dig_pred = np.concatenate([(Hte[i:i + 8192].float() @ Mq.T).argmax(1).numpy()\n                                           for i in range(0, len(Hte), 8192)])\n                share, rate, mq = _flip_stats(margins, dig_pred, yte, preds, sig)\n                rec.update({"sigma_hat": sig, "margin_quantiles": mq, "bin_edges": BINS[:-1],\n                            "bin_share": share, "bin_flip_rate": rate})\n            rec.update({"acc_mean": acc.mean(0).tolist(), "acc_std": acc.std(0).tolist(),\n                        "acc_min": acc.min(0).tolist(), "acc_chips": acc.round(5).tolist()})\n            out.append(rec)\n    for r in out:\n        r["train_seconds"] = round(t_train, 1)\n        r["job_seconds"] = round(time.time() - t0, 1)\n    return out\n\n\ndef build_jobs(stage: str, p: dict, data_home: str) -> list[dict]:\n    jobs = []\n    for d, e, dim, s, c in itertools.product(\n            p["datasets"].split(","), p["encoders"].split(","),\n            sorted(map(int, p["dims"].split(",")), reverse=True),\n            map(int, p["seeds"].split(",")), map(int, p["center"].split(","))):\n        if e == "idlevel" and not c:\n            continue\n        j = {"stage": stage, "dataset": d, "encoder": e, "dim": dim, "seed": s, "center": bool(c),\n             "methods": p["methods"].split(","), "precisions": p["precisions"].split(","),\n             "devices": p["devices"].split(","), "noise": [float(v) for v in p["noise"].split(",")],\n             "peripheries": p["peripheries"].split(","), "e2e": bool(int(p["e2e"])),\n             "n_chips": int(p["n_chips"]), "data_home": data_home}\n        j["job_key"] = job_key(j)\n        jobs.append(j)\n    return jobs\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("stage", choices=list(STAGES))\n    ap.add_argument("--workers", type=int, default=os.cpu_count())\n    ap.add_argument("--outdir", default="results")\n    ap.add_argument("--data_home", default="./data")\n    for k in ["datasets", "encoders", "dims", "seeds", "center", "methods", "precisions",\n              "devices", "noise", "peripheries", "e2e", "n_chips"]:\n        ap.add_argument(f"--{k}", default=None, help="override the stage preset")\n    a = ap.parse_args()\n    p = {k: (getattr(a, k) if getattr(a, k) is not None else v) for k, v in STAGES[a.stage].items()}\n\n    out = Path(a.outdir)\n    out.mkdir(parents=True, exist_ok=True)\n    path = out / f"v2_{a.stage}.jsonl"\n\n    from hdc import load_dataset\n    ok = []\n    for d in p["datasets"].split(","):  # download once, before forking workers\n        try:\n            load_dataset(d, a.data_home)\n            ok.append(d)\n        except Exception as e:  # keep going with the datasets that are available\n            print(f"WARNING: dataset {d} could not be loaded ({e!r}); skipping it", flush=True)\n    p["datasets"] = ",".join(ok)\n\n    jobs = build_jobs(a.stage, p, a.data_home)\n    todo = [j for j in jobs if j["job_key"] not in done_keys(path)]\n    # biggest datasets and dimensions first, so stragglers are small\n    print(f"[{a.stage}] {len(jobs)} jobs, {len(jobs) - len(todo)} done, running {len(todo)} "\n          f"on {a.workers} workers -> {path}", flush=True)\n    t_start = time.time()\n    with ProcessPoolExecutor(max_workers=a.workers) as ex, path.open("a") as f:\n        futs = {ex.submit(_worker, j): j for j in todo}\n        for i, fu in enumerate(as_completed(futs), 1):\n            j = futs[fu]\n            try:\n                recs = fu.result()\n            except Exception as e:\n                print(f"FAILED {j[\'dataset\']} {j[\'encoder\']} D={j[\'dim\']} seed={j[\'seed\']}: {e!r}",\n                      flush=True)\n                continue\n            for r in recs:\n                f.write(json.dumps(r) + "\\n")\n            f.flush()\n            el = time.time() - t_start\n            eta = el / i * (len(todo) - i)\n            best = max(recs, key=lambda r: r["acc_mean"][1 if len(r["times"]) > 1 else 0])\n            print(f"[{i}/{len(todo)}] {j[\'dataset\']} {j[\'encoder\']} D={j[\'dim\']} seed={j[\'seed\']} "\n                  f"centre={j[\'center\']}: best analog@1d {best[\'acc_mean\'][1]:.3f} "\n                  f"({best[\'method\']}/{best[\'precision\']}/{best[\'device\']}) "\n                  f"[{recs[0][\'job_seconds\']}s, elapsed {el/3600:.1f} h, ETA {eta/3600:.1f} h]",\n                  flush=True)\n\n\nif __name__ == "__main__":\n    main()\n', 'sweep_predict.py': '"""Supplementary stage: margin-to-noise predictions for an already finished stage.\n\nFor every job in results/v2_<stage>.jsonl it rebuilds the encoder and retrains every\nprototype set with the *stored* hyperparameters (lr and the margin actually used, so the\nnoise-calibrated method is reproduced exactly), checks that the digital test accuracy\nequals the stored value (training is deterministic), then programs ONE fresh calibration\nchip per (method, precision, device, noise, periphery) and records, at every time of the\ngrid and using training data only:\n  sigma_hat_t   std of the analog-minus-digital cosine error\n  sigma_diff_t  std of the error difference between the true class and its strongest\n                digital competitor (the quantity that actually moves decisions)\nand the test accuracy predicted from digital scores + Gaussian noise for both\n(pred_acc_t with sigma_hat, pred_acc_diff_t with sigma_diff / sqrt 2). No test-set\ndevice simulation is involved. Output: results/v2_<stage>_pred.jsonl, resumable.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport collections\nimport json\nimport os\nimport time\nfrom concurrent.futures import ProcessPoolExecutor, as_completed\nfrom pathlib import Path\n\nEPOCHS = 20\nFLIP_P = 0.05\nN_CAL = 5000\n\n\ndef _worker(job: dict) -> list[dict]:\n    os.environ.setdefault("OMP_NUM_THREADS", "1")\n    import numpy as np\n    import torch\n    torch.set_num_threads(1)\n    from hdc import (accuracy_digital, build_crossbar, calibrate_input_scale, load_dataset,\n                     make_encoder, make_inference_config, predict_accuracy_gaussian, quantize,\n                     train_prototypes)\n\n    t0 = time.time()\n    r0 = job["recs"][0]\n    Xtr, ytr, Xte, yte, C = load_dataset(r0["dataset"], job["data_home"])\n    enc = make_encoder(r0["encoder"], Xtr.shape[1], r0["dim"], r0["seed"], Xtr, center=r0["center"])\n    Htr, Hte = enc(Xtr), enc(Xte)\n    cal_idx = torch.randperm(len(Htr), generator=torch.Generator().manual_seed(1))[:N_CAL]\n    H_cal, y_cal = Htr[cal_idx], ytr[cal_idx.numpy()]\n    D = r0["dim"]\n    models = {}\n    out = []\n    for r in job["recs"]:\n        m = r["method"]\n        mkey = (m, r["margin_used"])  # noisecal has a different margin per device / precision\n        if mkey not in models:\n            kw = dict(seed=r["seed"])\n            if m != "single":\n                kw.update(lr=r["lr"])\n            if m in ("largemargin", "dependable", "noisecal"):\n                kw.update(margin=r["margin_used"])\n            if m == "dependable":\n                kw.update(flip_p=FLIP_P)\n            if m == "onlinehd":\n                kw.update(adaptive=True)\n            models[mkey] = train_prototypes(Htr, ytr, C, 0 if m == "single" else EPOCHS, **kw)\n        Mq = quantize(models[mkey], r["precision"])\n        dig = accuracy_digital(Mq, Hte, yte)\n        cfg = make_inference_config(r["device"], r["periphery"], noise_scale=r["noise_scale"])\n        s = calibrate_input_scale(Mq, H_cal) if r["periphery"] == "realistic" else 1.0\n        # one fresh calibration chip, training data only\n        norm = (Mq.norm(dim=1) * np.sqrt(D)).numpy()\n        R = (H_cal.float() @ Mq.T).numpy() / norm\n        comp = np.where(np.arange(C)[None, :] == y_cal[:, None], -np.inf, R).argmax(1)\n        idx = np.arange(len(y_cal))\n        layer = build_crossbar(Mq, cfg)\n        layer.program_analog_weights()\n        sh, sd = [], []\n        with torch.no_grad():\n            for t in r["times"]:\n                layer.drift_analog_weights(t)\n                A = layer(H_cal.float() * s).numpy() / s / norm\n                E = A - R\n                sh.append(float(E.std()))\n                sd.append(float((E[idx, y_cal] - E[idx, comp]).std()))\n        out.append({\n            "job_key": r["job_key"], "method": m, "precision": r["precision"],\n            "device": r["device"], "noise_scale": r["noise_scale"], "periphery": r["periphery"],\n            "digital_acc_rebuilt": dig, "digital_acc_stored": r["digital_acc"],\n            "reproduced": abs(dig - r["digital_acc"]) < 1e-9, "in_scale": s,\n            "times": r["times"], "sigma_hat_t": sh, "sigma_diff_t": sd,\n            "pred_acc_t": [predict_accuracy_gaussian(Mq, Hte, yte, v, seed=r["seed"]) for v in sh],\n            "pred_acc_diff_t": [predict_accuracy_gaussian(Mq, Hte, yte, v / np.sqrt(2), seed=r["seed"])\n                                for v in sd],\n        })\n    for o in out:\n        o["job_seconds"] = round(time.time() - t0, 1)\n    return out\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("stage")\n    ap.add_argument("--workers", type=int, default=os.cpu_count())\n    ap.add_argument("--outdir", default="results")\n    ap.add_argument("--data_home", default="./data")\n    a = ap.parse_args()\n    src = Path(a.outdir) / f"v2_{a.stage}.jsonl"\n    dst = Path(a.outdir) / f"v2_{a.stage}_pred.jsonl"\n    keep = ("job_key", "dataset", "encoder", "dim", "seed", "center", "method", "precision",\n            "device", "noise_scale", "periphery", "lr", "margin_used", "digital_acc", "times",\n            "e2e")\n    by_job = collections.OrderedDict()\n    for line in src.read_text().splitlines():\n        if not line.strip():\n            continue\n        r = json.loads(line)\n        if r.get("e2e"):\n            continue  # end-to-end records have no single-crossbar prediction\n        by_job.setdefault(r["job_key"], []).append({k: r[k] for k in keep})\n    done = set()\n    if dst.exists():\n        for line in dst.read_text().splitlines():\n            try:\n                done.add(json.loads(line)["job_key"])\n            except (json.JSONDecodeError, KeyError):\n                pass\n    from hdc import load_dataset\n    for ds in sorted({v[0]["dataset"] for v in by_job.values()}):\n        load_dataset(ds, a.data_home)\n    jobs = [{"recs": v, "data_home": a.data_home} for k, v in by_job.items() if k not in done]\n    jobs.sort(key=lambda j: -j["recs"][0]["dim"])\n    print(f"[predict {a.stage}] {len(by_job)} jobs, {len(by_job) - len(jobs)} done, running "\n          f"{len(jobs)} on {a.workers} workers -> {dst}", flush=True)\n    t_start = time.time()\n    bad = 0\n    with ProcessPoolExecutor(max_workers=a.workers) as ex, dst.open("a") as f:\n        futs = {ex.submit(_worker, j): j for j in jobs}\n        for i, fu in enumerate(as_completed(futs), 1):\n            r0 = futs[fu]["recs"][0]\n            try:\n                recs = fu.result()\n            except Exception as e:\n                print(f"FAILED {r0[\'dataset\']} {r0[\'encoder\']} D={r0[\'dim\']} seed={r0[\'seed\']}: {e!r}",\n                      flush=True)\n                continue\n            for r in recs:\n                f.write(json.dumps(r) + "\\n")\n            f.flush()\n            nbad = sum(not r["reproduced"] for r in recs)\n            bad += nbad\n            el = time.time() - t_start\n            print(f"[{i}/{len(jobs)}] {r0[\'dataset\']} {r0[\'encoder\']} D={r0[\'dim\']} seed={r0[\'seed\']}: "\n                  f"{len(recs)} records, models reproduced {len(recs) - nbad}/{len(recs)} "\n                  f"[{recs[0][\'job_seconds\']}s, elapsed {el/3600:.1f} h, "\n                  f"ETA {el / i * (len(jobs) - i) / 3600:.1f} h]", flush=True)\n    print(f"done; records whose digital accuracy did not reproduce: {bad}", flush=True)\n\n\nif __name__ == "__main__":\n    main()\n', 'sweep_analytic.py': '"""Supplementary stage: CLOSED-FORM (simulation-free) predictions for a finished stage.\n\nSame reconstruction as sweep_predict.py (models retrained with the stored hyperparameters,\ndigital accuracy checked), but instead of a calibration chip it uses only single-device\nstatistics (analytic.py): predicted accuracy at every time of the grid and the analytic\nsigma_Delta. No crossbar is programmed. Output: results/v2_<stage>_analytic.jsonl.\n\n--- original description of the calibration-chip variant follows ---\nSupplementary stage: margin-to-noise predictions for an already finished stage.\n\nFor every job in results/v2_<stage>.jsonl it rebuilds the encoder and retrains every\nprototype set with the *stored* hyperparameters (lr and the margin actually used, so the\nnoise-calibrated method is reproduced exactly), checks that the digital test accuracy\nequals the stored value (training is deterministic), then programs ONE fresh calibration\nchip per (method, precision, device, noise, periphery) and records, at every time of the\ngrid and using training data only:\n  sigma_hat_t   std of the analog-minus-digital cosine error\n  sigma_diff_t  std of the error difference between the true class and its strongest\n                digital competitor (the quantity that actually moves decisions)\nand the test accuracy predicted from digital scores + Gaussian noise for both\n(pred_acc_t with sigma_hat, pred_acc_diff_t with sigma_diff / sqrt 2). No test-set\ndevice simulation is involved. Output: results/v2_<stage>_pred.jsonl, resumable.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport collections\nimport json\nimport os\nimport time\nfrom concurrent.futures import ProcessPoolExecutor, as_completed\nfrom pathlib import Path\n\nEPOCHS = 20\nFLIP_P = 0.05\nN_CAL = 5000\n\n\ndef _worker(job: dict) -> list[dict]:\n    os.environ.setdefault("OMP_NUM_THREADS", "1")\n    import numpy as np\n    import torch\n    torch.set_num_threads(1)\n    from analytic import predict_accuracy_analytic, sigma_delta_analytic\n    from hdc import (accuracy_digital, calibrate_input_scale, load_dataset, make_encoder,\n                     quantize, train_prototypes)\n\n    t0 = time.time()\n    r0 = job["recs"][0]\n    Xtr, ytr, Xte, yte, C = load_dataset(r0["dataset"], job["data_home"])\n    enc = make_encoder(r0["encoder"], Xtr.shape[1], r0["dim"], r0["seed"], Xtr, center=r0["center"])\n    Htr, Hte = enc(Xtr), enc(Xte)\n    cal_idx = torch.randperm(len(Htr), generator=torch.Generator().manual_seed(1))[:N_CAL]\n    H_cal, y_cal = Htr[cal_idx], ytr[cal_idx.numpy()]\n    D = r0["dim"]\n    models = {}\n    out = []\n    for r in job["recs"]:\n        m = r["method"]\n        mkey = (m, r["margin_used"])  # noisecal has a different margin per device / precision\n        if mkey not in models:\n            kw = dict(seed=r["seed"])\n            if m != "single":\n                kw.update(lr=r["lr"])\n            if m in ("largemargin", "dependable", "noisecal"):\n                kw.update(margin=r["margin_used"])\n            if m == "dependable":\n                kw.update(flip_p=FLIP_P)\n            if m == "onlinehd":\n                kw.update(adaptive=True)\n            models[mkey] = train_prototypes(Htr, ytr, C, 0 if m == "single" else EPOCHS, **kw)\n        Mq = quantize(models[mkey], r["precision"])\n        dig = accuracy_digital(Mq, Hte, yte)\n        s = calibrate_input_scale(Mq, H_cal) if r["periphery"] == "realistic" else 1.0\n        out.append({\n            "job_key": r["job_key"], "method": m, "precision": r["precision"],\n            "device": r["device"], "noise_scale": r["noise_scale"], "periphery": r["periphery"],\n            "digital_acc_rebuilt": dig, "digital_acc_stored": r["digital_acc"],\n            "reproduced": abs(dig - r["digital_acc"]) < 1e-9, "in_scale": s, "times": r["times"],\n            "sigma_delta_analytic_t": [sigma_delta_analytic(Mq, H_cal, y_cal, r["device"], t, s,\n                                                            r["periphery"], r["noise_scale"])\n                                       for t in r["times"]],\n            "pred_acc_analytic_t": [predict_accuracy_analytic(Mq, Hte, yte, r["device"], t, s,\n                                                              r["periphery"], r["noise_scale"],\n                                                              seed=r["seed"])\n                                    for t in r["times"]],\n        })\n    for o in out:\n        o["job_seconds"] = round(time.time() - t0, 1)\n    return out\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("stages", help="comma-separated, e.g. core or stress,encoders,precision")\n    ap.add_argument("--workers", type=int, default=os.cpu_count())\n    ap.add_argument("--outdir", default="results")\n    ap.add_argument("--data_home", default="./data")\n    a = ap.parse_args()\n    for stage in a.stages.split(","):\n        a.stage = stage\n        run_stage(a)\n\n\ndef run_stage(a):\n    src = Path(a.outdir) / f"v2_{a.stage}.jsonl"\n    dst = Path(a.outdir) / f"v2_{a.stage}_analytic.jsonl"\n    keep = ("job_key", "dataset", "encoder", "dim", "seed", "center", "method", "precision",\n            "device", "noise_scale", "periphery", "lr", "margin_used", "digital_acc", "times",\n            "e2e")\n    by_job = collections.OrderedDict()\n    for line in src.read_text().splitlines():\n        if not line.strip():\n            continue\n        r = json.loads(line)\n        if r.get("e2e"):\n            continue  # end-to-end records have no single-crossbar prediction\n        by_job.setdefault(r["job_key"], []).append({k: r[k] for k in keep})\n    done = set()\n    if dst.exists():\n        for line in dst.read_text().splitlines():\n            try:\n                done.add(json.loads(line)["job_key"])\n            except (json.JSONDecodeError, KeyError):\n                pass\n    from hdc import load_dataset\n    for ds in sorted({v[0]["dataset"] for v in by_job.values()}):\n        load_dataset(ds, a.data_home)\n    jobs = [{"recs": v, "data_home": a.data_home} for k, v in by_job.items() if k not in done]\n    jobs.sort(key=lambda j: -j["recs"][0]["dim"])\n    print(f"[analytic {a.stage}] {len(by_job)} jobs, {len(by_job) - len(jobs)} done, running "\n          f"{len(jobs)} on {a.workers} workers -> {dst}", flush=True)\n    t_start = time.time()\n    bad = 0\n    with ProcessPoolExecutor(max_workers=a.workers) as ex, dst.open("a") as f:\n        futs = {ex.submit(_worker, j): j for j in jobs}\n        for i, fu in enumerate(as_completed(futs), 1):\n            r0 = futs[fu]["recs"][0]\n            try:\n                recs = fu.result()\n            except Exception as e:\n                print(f"FAILED {r0[\'dataset\']} {r0[\'encoder\']} D={r0[\'dim\']} seed={r0[\'seed\']}: {e!r}",\n                      flush=True)\n                continue\n            for r in recs:\n                f.write(json.dumps(r) + "\\n")\n            f.flush()\n            nbad = sum(not r["reproduced"] for r in recs)\n            bad += nbad\n            el = time.time() - t_start\n            print(f"[{i}/{len(jobs)}] {r0[\'dataset\']} {r0[\'encoder\']} D={r0[\'dim\']} seed={r0[\'seed\']}: "\n                  f"{len(recs)} records, models reproduced {len(recs) - nbad}/{len(recs)} "\n                  f"[{recs[0][\'job_seconds\']}s, elapsed {el/3600:.1f} h, "\n                  f"ETA {el / i * (len(jobs) - i) / 3600:.1f} h]", flush=True)\n    print(f"done; records whose digital accuracy did not reproduce: {bad}", flush=True)\n\n\nif __name__ == "__main__":\n    main()\n', 'sweep_analytic2.py': '"""Supplementary stage: periphery-aware CLOSED-FORM predictions (analytic.py, v2).\n\nSame reconstruction as sweep_analytic.py (models retrained with the stored hyperparameters,\ndigital accuracy checked). v2 adds the three effects found in the v1 validation and still\nuses no device simulation: DAC-quantised read scale, per-tile read gain of the Wan-2022\nReRAM model (largest programmed weight; exact extreme-value CDF), and per-tile ADC clipping\n+ rounding before drift compensation. Records pred_acc_analytic2_t and clip_frac_t.\nOutput: results/v2_<stage>_analytic2.jsonl (resumable).\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport collections\nimport json\nimport os\nimport time\nfrom concurrent.futures import ProcessPoolExecutor, as_completed\nfrom pathlib import Path\n\nEPOCHS = 20\nFLIP_P = 0.05\nN_CAL = 5000\n\n\ndef _v2(Mq, Hte, yte, r, s):\n    from analytic import predict_accuracy_analytic2\n    acc, clip = [], []\n    for t in r["times"]:\n        if r["periphery"] == "realistic":\n            a, c = predict_accuracy_analytic2(Mq, Hte, yte, r["device"], t, s, r["periphery"],\n                                              r["noise_scale"], seed=r["seed"], return_parts=True)\n        else:\n            a, c = predict_accuracy_analytic2(Mq, Hte, yte, r["device"], t, s, r["periphery"],\n                                              r["noise_scale"], seed=r["seed"]), 0.0\n        acc.append(a)\n        clip.append(float(c))\n    return {"pred_acc_analytic2_t": acc, "clip_frac_t": clip}\n\n\ndef _worker(job: dict) -> list[dict]:\n    os.environ.setdefault("OMP_NUM_THREADS", "1")\n    import numpy as np\n    import torch\n    torch.set_num_threads(1)\n    from analytic import predict_accuracy_analytic2\n    from hdc import (accuracy_digital, calibrate_input_scale, load_dataset, make_encoder,\n                     quantize, train_prototypes)\n\n    t0 = time.time()\n    r0 = job["recs"][0]\n    Xtr, ytr, Xte, yte, C = load_dataset(r0["dataset"], job["data_home"])\n    enc = make_encoder(r0["encoder"], Xtr.shape[1], r0["dim"], r0["seed"], Xtr, center=r0["center"])\n    Htr, Hte = enc(Xtr), enc(Xte)\n    cal_idx = torch.randperm(len(Htr), generator=torch.Generator().manual_seed(1))[:N_CAL]\n    H_cal, y_cal = Htr[cal_idx], ytr[cal_idx.numpy()]\n    D = r0["dim"]\n    models = {}\n    out = []\n    for r in job["recs"]:\n        m = r["method"]\n        mkey = (m, r["margin_used"])  # noisecal has a different margin per device / precision\n        if mkey not in models:\n            kw = dict(seed=r["seed"])\n            if m != "single":\n                kw.update(lr=r["lr"])\n            if m in ("largemargin", "dependable", "noisecal"):\n                kw.update(margin=r["margin_used"])\n            if m == "dependable":\n                kw.update(flip_p=FLIP_P)\n            if m == "onlinehd":\n                kw.update(adaptive=True)\n            models[mkey] = train_prototypes(Htr, ytr, C, 0 if m == "single" else EPOCHS, **kw)\n        Mq = quantize(models[mkey], r["precision"])\n        dig = accuracy_digital(Mq, Hte, yte)\n        s = calibrate_input_scale(Mq, H_cal) if r["periphery"] == "realistic" else 1.0\n        out.append({\n            "job_key": r["job_key"], "method": m, "precision": r["precision"],\n            "device": r["device"], "noise_scale": r["noise_scale"], "periphery": r["periphery"],\n            "digital_acc_rebuilt": dig, "digital_acc_stored": r["digital_acc"],\n            "reproduced": abs(dig - r["digital_acc"]) < 1e-9, "in_scale": s, "times": r["times"],\n            **_v2(Mq, Hte, yte, r, s),\n        })\n    for o in out:\n        o["job_seconds"] = round(time.time() - t0, 1)\n    return out\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("stages", help="comma-separated, e.g. core or stress,encoders,precision")\n    ap.add_argument("--workers", type=int, default=os.cpu_count())\n    ap.add_argument("--outdir", default="results")\n    ap.add_argument("--data_home", default="./data")\n    a = ap.parse_args()\n    for stage in a.stages.split(","):\n        a.stage = stage\n        run_stage(a)\n\n\ndef run_stage(a):\n    src = Path(a.outdir) / f"v2_{a.stage}.jsonl"\n    dst = Path(a.outdir) / f"v2_{a.stage}_analytic2.jsonl"\n    keep = ("job_key", "dataset", "encoder", "dim", "seed", "center", "method", "precision",\n            "device", "noise_scale", "periphery", "lr", "margin_used", "digital_acc", "times",\n            "e2e")\n    by_job = collections.OrderedDict()\n    for line in src.read_text().splitlines():\n        if not line.strip():\n            continue\n        r = json.loads(line)\n        if r.get("e2e"):\n            continue  # end-to-end records have no single-crossbar prediction\n        by_job.setdefault(r["job_key"], []).append({k: r[k] for k in keep})\n    done = set()\n    if dst.exists():\n        for line in dst.read_text().splitlines():\n            try:\n                done.add(json.loads(line)["job_key"])\n            except (json.JSONDecodeError, KeyError):\n                pass\n    from hdc import load_dataset\n    for ds in sorted({v[0]["dataset"] for v in by_job.values()}):\n        load_dataset(ds, a.data_home)\n    jobs = [{"recs": v, "data_home": a.data_home} for k, v in by_job.items() if k not in done]\n    jobs.sort(key=lambda j: -j["recs"][0]["dim"])\n    print(f"[analytic2 {a.stage}] {len(by_job)} jobs, {len(by_job) - len(jobs)} done, running "\n          f"{len(jobs)} on {a.workers} workers -> {dst}", flush=True)\n    t_start = time.time()\n    bad = 0\n    with ProcessPoolExecutor(max_workers=a.workers) as ex, dst.open("a") as f:\n        futs = {ex.submit(_worker, j): j for j in jobs}\n        for i, fu in enumerate(as_completed(futs), 1):\n            r0 = futs[fu]["recs"][0]\n            try:\n                recs = fu.result()\n            except Exception as e:\n                print(f"FAILED {r0[\'dataset\']} {r0[\'encoder\']} D={r0[\'dim\']} seed={r0[\'seed\']}: {e!r}",\n                      flush=True)\n                continue\n            for r in recs:\n                f.write(json.dumps(r) + "\\n")\n            f.flush()\n            nbad = sum(not r["reproduced"] for r in recs)\n            bad += nbad\n            el = time.time() - t_start\n            print(f"[{i}/{len(jobs)}] {r0[\'dataset\']} {r0[\'encoder\']} D={r0[\'dim\']} seed={r0[\'seed\']}: "\n                  f"{len(recs)} records, models reproduced {len(recs) - nbad}/{len(recs)} "\n                  f"[{recs[0][\'job_seconds\']}s, elapsed {el/3600:.1f} h, "\n                  f"ETA {el / i * (len(jobs) - i) / 3600:.1f} h]", flush=True)\n    print(f"done; records whose digital accuracy did not reproduce: {bad}", flush=True)\n\n\nif __name__ == "__main__":\n    main()\n'}

for name, txt in FILES.items():
    (work / "code_langid" / name).write_text(txt)

ENV = pathlib.Path("/content/hdc_env")
PY = ENV / "bin" / "python"
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "uv"], check=True)
if not PY.exists():
    subprocess.run([sys.executable, "-m", "uv", "venv", "-q", "-p", "3.12", str(ENV)], check=True)
subprocess.run([sys.executable, "-m", "uv", "pip", "install", "-q", "--python", str(PY),
                "aihwkit==1.1.0", "torch==2.10.0", "torchvision==0.25.0", "scikit-learn", "scipy", "pandas"],
               check=True)
print("CPU cores:", os.cpu_count())

thr = {v: "1" for v in ("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS", "NUMEXPR_NUM_THREADS")}
log = work / "results" / "v2_langid.log"
common = ["--outdir", str(work / "results"), "--data_home", str(work / "data"), "--workers", str(os.cpu_count())]
for script in ["sweep_hdc2.py", "sweep_predict.py", "sweep_analytic.py", "sweep_analytic2.py"]:
    cmd = [str(PY), script, "langid", *common]
    print("\n==== running:", " ".join(cmd), flush=True)
    with open(log, "a") as fh:
        p = subprocess.Popen(cmd, cwd=work / "code_langid", stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                             text=True, env={**os.environ, **thr, "PYTHONWARNINGS": "ignore"})
        for line in p.stdout:
            fh.write(line); fh.flush()
            if "Warning" not in line:
                print(line, end="")
    rc = p.wait()
    print("exit code", rc)
    if rc != 0:
        raise SystemExit(f"{script} failed; see {log}")
